// Hand-CUDA n512 wide-trailing (brief-41): EXPLICIT-smem fused trailing matching
// the Triton _trailing_fused_kernel (grid=(col_tiles, B), one block per
// (col_tile, matrix)). RTN-tf32x2 accuracy (round-to-nearest split of V, hi+lo
// split of A). Goal: cp.async ring-buffer staging sized to fit block-limit>=9
// (smem<=24KB at 3-deep), so more eligible warps hide the MMA-dependency latency
// that walls the Triton tile at block-limit-7 / 28KB.
//
// Per block: BLK=32 reflectors, BNc=32 trail cols, reduce over pheight rows in
// chunks of BM=32. W=V^T@A (32x32), YT=T^T@W (32x32), A_trail-=V@YT.
#include <mma.h>
#include <cuda/pipeline>
using namespace nvcuda;

// 16x16x8 tf32 WMMA fragments.
typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragA_rm;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragB_rm;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::col_major> FragB_cm;
typedef wmma::fragment<wmma::accumulator, 16, 16, 8, float> FragAcc;

__device__ __forceinline__ float rtn_tf32(float v) {
    // round-to-nearest tf32: add half-ulp of dropped 13 mantissa bits, mask low 13.
    int i = __float_as_int(v);
    i = (i + 0x1000) & 0xFFFFE000;
    return __int_as_float(i);
}
__device__ __forceinline__ float trunc_tf32(float v) {
    int i = __float_as_int(v) & 0xFFFFE000;
    return __int_as_float(i);
}

// Stage layout in smem ring buffer (NS stages). Each stage holds:
//   sA[stage]: BM x BNc  A_trail chunk (row-major, BM rows x BNc cols)   -> 32*32*4 = 4096 B
//   sV[stage]: BLK x BM  V^T chunk      (row-major, BLK refl x BM cols)  -> 32*32*4 = 4096 B
// per stage = 8192 B. NS=3 -> 24576 B. NS=2 -> 16384 B.
//
// Threads: NW warps. Each warp owns a (16x16) output tile of W. W is 32x32 = 2x2
// tiles. With NW=2, warp w owns tiles {w, w+2} (round-robin over 4 tiles). The W
// accumulators are WMMA accumulator fragments held in registers across the whole
// reduction (NOT staged in smem) -- this is the decoupling the brief asks for.

extern "C" __global__ void wt_fused(
    const float* __restrict__ A,      // (B, N, N) row-major
    const float* __restrict__ Vbuf,   // (B, BLK, N)  Vt[k, r]
    const float* __restrict__ Tbuf,   // (B, BLK, BLK) T factor
    float* __restrict__ Aout,         // (B, N, N) row-major (store dest)
    int B, int N, int j, int pheight, int ncols, int jb,
    int strideAb, int strideAn,
    int strideVb, int strideVk, int strideVn,
    int strideTb, int strideTk, int strideTn,
    int BLK, int BM, int BNc, int NS, int PREC)
{
    const int col_tile = blockIdx.x;
    const int bid      = blockIdx.y;
    if (bid >= B) return;
    const int c0  = col_tile * BNc;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;
    const int NW = nthr >> 5;

    extern __shared__ float smem[];
    const int stageFloats = BM * BNc + BLK * BM;   // floats per stage
    // sA[stage] at smem + stage*stageFloats ; sV[stage] at + BM*BNc
    float* sAbase = smem;
    float* sVbase = smem + BM * BNc;

    const float* Ab = A + (long)bid * strideAb + (long)j * strideAn + jb;   // A_trail[0,0]
    const float* Vb = Vbuf + (long)bid * strideVb;                          // Vt[0,0]

    const int nchunks = (pheight + BM - 1) / BM;

    // W accumulators (each warp owns a subset of the 2x2=4 output tiles).
    const int mt = BLK / 16;   // 2
    const int nt = BNc / 16;   // 2
    const int ntiles = mt * nt;
    FragAcc accW[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accW[t], 0.0f);

    auto block = cooperative_groups::this_thread_block();

    // ---- cp.async pipelined load helper ----
    // Load chunk ci's A (BM x BNc) and V^T (BLK x BM) into stage buffer (ci % NS).
    auto load_chunk = [&](int ci, int stage) {
        float* sA = sAbase + (long)stage * stageFloats;
        float* sV = sVbase + (long)stage * stageFloats;
        const int r0 = ci * BM;
        // A chunk: BM rows x BNc cols, A_trail[r0+rr, c0+cc]
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc;
            int cc = idx % BNc;
            int gr = r0 + rr;
            int gc = c0 + cc;
            float v = 0.0f;
            if (gr < pheight && gc < ncols)
                v = Ab[(long)gr * strideAn + gc];
            sA[idx] = v;
        }
        // V chunk: BLK refl x BM cols, Vt[k, r0+rr]
        for (int idx = tid; idx < BLK * BM; idx += nthr) {
            int k  = idx / BM;
            int rr = idx % BM;
            int gr = r0 + rr;
            float v = 0.0f;
            if (gr < pheight)
                v = Vb[(long)k * strideVk + (long)gr * strideVn];
            sV[idx] = v;
        }
    };

    // Prologue: load first min(NS-1, nchunks) chunks.
    int prefetch = NS - 1;
    if (prefetch > nchunks) prefetch = nchunks;
    for (int ci = 0; ci < prefetch; ++ci) {
        load_chunk(ci, ci % NS);
    }
    __syncthreads();

    // Main reduction loop.
    for (int ci = 0; ci < nchunks; ++ci) {
        int stage = ci % NS;
        // issue prefetch of chunk ci+prefetch
        int nx = ci + prefetch;
        if (nx < nchunks) {
            load_chunk(nx, nx % NS);
        }
        __syncthreads();

        float* sA = sAbase + (long)stage * stageFloats;
        float* sV = sVbase + (long)stage * stageFloats;

        // W += V^T @ A over the BM=32 = 4 k-subtiles of 8.
        const int kt = BM / 8;   // 4
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            int mi = t / nt;     // reflector tile row
            int ni = t % nt;     // col tile
            // round-robin across warps
            if ((t % NW) != warp) continue;
            for (int kk = 0; kk < kt; ++kk) {
                // A-frag = V^T[mi*16 + 0..16, kk*8 + 0..8] from sV (row-major, ldm=BM)
                FragA_rm a;
                wmma::load_matrix_sync(a, sV + (long)mi * 16 * BM + (long)kk * 8, BM);
                // B-frag = A_trail[kk*8 + 0..8, ni*16 + 0..16] from sA (row-major, ldm=BNc)
                FragB_rm b;
                wmma::load_matrix_sync(b, sA + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                // RTN-tf32x2: a rounded; b split hi+lo. acc += a_hi*b_hi + a_hi*b_lo
                FragA_rm ah;
                FragB_rm bh, bl;
                #pragma unroll
                for (int e = 0; e < a.num_elements; ++e) ah.x[e] = rtn_tf32(a.x[e]);
                #pragma unroll
                for (int e = 0; e < b.num_elements; ++e) { float hv = trunc_tf32(b.x[e]); bh.x[e] = hv; bl.x[e] = b.x[e] - hv; }
                wmma::mma_sync(accW[t], ah, bh, accW[t]);
                wmma::mma_sync(accW[t], ah, bl, accW[t]);
            }
        }
        __syncthreads();
    }

    // Stage W into smem so the whole block can read it for YT = T^T @ W.
    // Use the first BLK*BNc floats of smem.
    float* sW = smem;
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt;
        int ni = t % nt;
        // store accumulator tile (16x16) into sW row-major (ldm=BNc): rows = reflectors mi*16, cols ni*16
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accW[t], BNc, wmma::mem_row_major);
    }
    __syncthreads();

    // YT = T^T @ W  (BLK x BNc). T is (BLK,BLK). Load T into smem region after sW.
    float* sT = smem + BLK * BNc;       // BLK*BLK
    const float* Tb = Tbuf + (long)bid * strideTb;
    for (int idx = tid; idx < BLK * BLK; idx += nthr) {
        int r = idx / BLK;
        int cc = idx % BLK;
        sT[idx] = Tb[(long)r * strideTk + (long)cc * strideTn];
    }
    __syncthreads();

    // YT[a, n] = sum_k T[k, a] * W[k, n]  (T^T @ W). full-precision tf32x3 for the
    // tiny coupling dot (matches Triton which keeps YT at tf32x3). 32x32 = 4 tiles.
    FragAcc accYT[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accYT[t], 0.0f);
    {
        const int ktY = BLK / 8;  // 4
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt;   // YT row tile (a)
            int ni = t % nt;   // YT col tile (n)
            for (int kk = 0; kk < ktY; ++kk) {
                // A-frag = T^T[mi*16 +0..16 (a), kk*8 +0..8 (k)]. T^T[a,k]=T[k,a]=sT[k*BLK+a].
                // We need matrix_a row_major frag over (a rows, k cols) with element [a,k]=sT[k*BLK+a]
                // i.e. col_major view of sT with ldm=BLK. Use matrix_a col_major.
                wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::col_major> at;
                wmma::load_matrix_sync(at, sT + (long)mi * 16 + (long)kk * 8 * BLK, BLK);
                // B-frag = W[kk*8 +0..8 (k), ni*16 +0..16 (n)] from sW row_major ldm=BNc.
                FragB_rm bw;
                wmma::load_matrix_sync(bw, sW + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                // tf32x3 split (3 MMA) for the coupling dot.
                wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::col_major> ath, atl;
                FragB_rm bwh, bwl;
                #pragma unroll
                for (int e = 0; e < at.num_elements; ++e) { float hv = trunc_tf32(at.x[e]); ath.x[e]=hv; atl.x[e]=trunc_tf32(at.x[e]-hv); }
                #pragma unroll
                for (int e = 0; e < bw.num_elements; ++e) { float hv = trunc_tf32(bw.x[e]); bwh.x[e]=hv; bwl.x[e]=trunc_tf32(bw.x[e]-hv); }
                wmma::mma_sync(accYT[t], ath, bwh, accYT[t]);
                wmma::mma_sync(accYT[t], ath, bwl, accYT[t]);
                wmma::mma_sync(accYT[t], atl, bwh, accYT[t]);
            }
        }
    }
    // store YT into sW (overwrite W; we no longer need W).
    __syncthreads();
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt;
        int ni = t % nt;
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accYT[t], BNc, wmma::mem_row_major);
    }
    __syncthreads();
    // sW now holds YT (BLK x BNc), row-major ldm=BNc: YT[a, n] = sW[a*BNc + n].

    // sweep 2: A_trail[r, n] -= sum_a V[r, a] * YT[a, n].  V[r,a] = Vt[a, r] = Vbuf[a, r].
    // delta = V @ YT. Reduce over a in [0,BLK). chunk rows of BM.
    const float* AbR = A + (long)bid * strideAb + (long)j * strideAn + jb;
    float* AoutR = Aout + (long)bid * strideAb + (long)j * strideAn + jb;
    // We process the same chunks; load V (BM x BLK) and compute delta (BM x BNc), then store A - delta.
    // Use sV region (after sW + sT) for the V chunk and reuse sA for A original.
    float* s2V = smem + BLK * BNc + BLK * BLK;       // BM*BLK
    float* s2A = s2V + BM * BLK;                      // BM*BNc

    for (int ci = 0; ci < nchunks; ++ci) {
        int r0 = ci * BM;
        // load V[r, a] = Vt[a, r] -> s2V[rr*BLK + a]  (BM rows x BLK cols, row-major ldm=BLK)
        for (int idx = tid; idx < BM * BLK; idx += nthr) {
            int rr = idx / BLK;
            int a = idx % BLK;
            int gr = r0 + rr;
            float v = 0.0f;
            if (gr < pheight) v = Vb[(long)a * strideVk + (long)gr * strideVn];
            s2V[idx] = v;
        }
        // load original A chunk -> s2A
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc;
            int cc = idx % BNc;
            int gr = r0 + rr, gc = c0 + cc;
            float v = 0.0f;
            if (gr < pheight && gc < ncols) v = AbR[(long)gr * strideAn + gc];
            s2A[idx] = v;
        }
        __syncthreads();
        // delta tiles (BM x BNc) = (V @ YT). BM=32 rows, BNc=32 cols, contract BLK=32.
        // 2x2 tiles. accumulate into local frag.
        const int ktD = BLK / 8;  // 4
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt;   // row tile (BM)
            int ni = t % nt;   // col tile (BNc)
            FragAcc accD; wmma::fill_fragment(accD, 0.0f);
            for (int kk = 0; kk < ktD; ++kk) {
                // A-frag = V[mi*16 +0..16 (r), kk*8 +0..8 (a)] from s2V row_major ldm=BLK
                FragA_rm vrow;
                wmma::load_matrix_sync(vrow, s2V + (long)mi * 16 * BLK + (long)kk * 8, BLK);
                // B-frag = YT[kk*8 +0..8 (a), ni*16 +0..16 (n)] from sW row_major ldm=BNc
                FragB_rm yt;
                wmma::load_matrix_sync(yt, sW + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                // RTN-tf32x2: V rounded, YT split hi+lo
                FragA_rm vh;
                FragB_rm yh, yl;
                #pragma unroll
                for (int e = 0; e < vrow.num_elements; ++e) vh.x[e] = rtn_tf32(vrow.x[e]);
                #pragma unroll
                for (int e = 0; e < yt.num_elements; ++e) { float hv = trunc_tf32(yt.x[e]); yh.x[e]=hv; yl.x[e]=yt.x[e]-hv; }
                wmma::mma_sync(accD, vh, yh, accD);
                wmma::mma_sync(accD, vh, yl, accD);
            }
            // store A - delta: read s2A tile, subtract accD, write Aout.
            // accD is a 16x16 acc fragment. store to a temp smem, then subtract.
            // Simpler: store delta into s2A region's tile location after reading orig? We have orig in s2A.
            // Write A-delta directly: store_matrix_sync writes delta; we need subtract from orig.
            // Use a small per-warp scratch in registers: store frag to global temp is awkward; instead
            // store delta into a smem delta buffer then elementwise subtract+store.
            // We'll store delta into sW2? no. Use store to s2A tile is wrong (race with orig).
            // Approach: store delta to a dedicated delta smem region.
            // (handled below by storing into sDelta)
            extern __shared__ float dummy[];   // placeholder; real store below
            (void)dummy;
            // store accD tile into a per-tile delta region overlapping s2A is unsafe; use sW? sW holds YT (shared, needed by other warps' kk loop already done for this ci). After the tile loop we no longer need YT for THIS ci? other warps still computing other tiles need YT. So cannot clobber sW.
            // Instead: compute final = orig - delta per-element from the fragment directly.
            // store delta to global Aout first as delta, then we lose orig. Do orig-delta in fragment space:
            // We can load orig into an accumulator-shaped fragment via load_matrix_sync(acc,...) then subtract.
            FragAcc accO;
            wmma::load_matrix_sync(accO, s2A + (long)mi * 16 * BNc + (long)ni * 16, BNc, wmma::mem_row_major);
            #pragma unroll
            for (int e = 0; e < accO.num_elements; ++e) accO.x[e] = accO.x[e] - accD.x[e];
            // store to Aout
            int gr0 = r0 + mi * 16;
            int gc0 = c0 + ni * 16;
            // guard: only store if fully in range (pheight, ncols multiples of 16 for n512 trailing? not always)
            if (gr0 + 16 <= pheight && gc0 + 16 <= ncols) {
                wmma::store_matrix_sync(AoutR + (long)gr0 * strideAn + gc0, accO, strideAn, wmma::mem_row_major);
            } else {
                // elementwise masked store via smem
                wmma::store_matrix_sync(s2A + (long)mi * 16 * BNc + (long)ni * 16, accO, BNc, wmma::mem_row_major);
            }
        }
        __syncthreads();
        // masked-tail elementwise store for partial tiles (rare; n512 ncols mult of 16 usually)
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc;
            int gr = r0 + rr, gc = c0 + cc;
            if (gr < pheight && gc < ncols) {
                int mi = rr / 16, ni = cc / 16;
                int gr0 = r0 + mi*16, gc0 = c0 + ni*16;
                if (!(gr0 + 16 <= pheight && gc0 + 16 <= ncols)) {
                    AoutR[(long)gr * strideAn + gc] = s2A[idx];
                }
            }
        }
        __syncthreads();
    }
}

