// Hand-CUDA n512 wide-trailing (brief-41): EXPLICIT-smem fused trailing matching
// the Triton _trailing_fused_kernel (grid=(col_tiles, B), one block per
// (col_tile, matrix)). RTN-tf32x2 accuracy. Goal: ring-buffer staging sized to
// fit block-limit>=9 (smem<=24KB) so eligible warps rise above the Triton tile's
// block-limit-7 / 28KB wall.
//
// Per block: BLK=32 reflectors, BNc=32 trail cols, reduce over pheight rows in
// chunks of BM=32. W=V^T@A (32x32), YT=T^T@W (32x32), A_trail -= V@YT.
// Block = NW warps (default 2 -> 64 threads). 4 output tiles (2x2 of 16x16),
// warp w owns tiles {t : t%NW==w}. Accumulators live in registers (decoupled
// from the smem ring).
#include <mma.h>
using namespace nvcuda;

typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragA_rm;
typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::col_major> FragA_cm;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragB_rm;
typedef wmma::fragment<wmma::accumulator, 16, 16, 8, float> FragAcc;

__device__ __forceinline__ float rtn_tf32(float v) {
    int i = __float_as_int(v);
    i = (i + 0x1000) & 0xFFFFE000;
    return __int_as_float(i);
}
__device__ __forceinline__ float trunc_tf32(float v) {
    return __int_as_float(__float_as_int(v) & 0xFFFFE000);
}

// smem layout (single dynamic buffer, reused across phases):
//  Phase reduce: ring of NS stages, each [ sA: BM*BNc | sV: BLK*BM ]  (8192 B/stage)
//  Phase YT:     sW (BLK*BNc) | sT (BLK*BLK)
//  Phase apply:  sW (BLK*BNc, holds YT) | s2V (BM*BLK) | s2A (BM*BNc)
// Peak = max(NS*8192, (BLK*BNc+BLK*BLK)*4, (BLK*BNc+BM*BLK+BM*BNc)*4).
// For 32/32/32: NS*8192, 4096+4096=8192, 4096+4096+4096=12288. NS=3 -> 24576 peak.

extern "C" __global__ void wt_fused(
    const float* __restrict__ A, const float* __restrict__ Vbuf,
    const float* __restrict__ Tbuf, float* __restrict__ Aout,
    int B, int N, int j, int pheight, int ncols, int jb,
    int strideAb, int strideAn,
    int strideVb, int strideVk, int strideVn,
    int strideTb, int strideTk, int strideTn,
    int BLK, int BM, int BNc, int NS, int PREC)
{
    const int col_tile = blockIdx.x;
    const int bid = blockIdx.y;
    if (bid >= B) return;
    const int c0 = col_tile * BNc;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int NW = nthr >> 5;

    extern __shared__ float smem[];
    const int stageFloats = BM * BNc + BLK * BM;
    const int nchunks = (pheight + BM - 1) / BM;
    const int mt = BLK / 16, nt = BNc / 16;
    const int ntiles = mt * nt;            // 4

    const float* Ab = A + (long)bid * strideAb + (long)j * strideAn + jb;
    const float* Vb = Vbuf + (long)bid * strideVb;

    // ---- reduction: W = V^T @ A_trail ----
    FragAcc accW[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accW[t], 0.0f);

    auto load_chunk = [&](int ci, int stage) {
        float* sA = smem + (long)stage * stageFloats;
        float* sV = sA + BM * BNc;
        const int r0 = ci * BM;
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
            sA[idx] = (gr < pheight && gc < ncols) ? Ab[(long)gr * strideAn + gc] : 0.0f;
        }
        for (int idx = tid; idx < BLK * BM; idx += nthr) {
            int k = idx / BM, rr = idx % BM, gr = r0 + rr;
            sV[idx] = (gr < pheight) ? Vb[(long)k * strideVk + (long)gr * strideVn] : 0.0f;
        }
    };

    int prefetch = NS - 1; if (prefetch > nchunks) prefetch = nchunks;
    for (int ci = 0; ci < prefetch; ++ci) load_chunk(ci, ci % NS);
    __syncthreads();

    const int kt = BM / 8;   // 4
    for (int ci = 0; ci < nchunks; ++ci) {
        int stage = ci % NS;
        int nx = ci + prefetch;
        if (nx < nchunks) load_chunk(nx, nx % NS);
        __syncthreads();
        float* sA = smem + (long)stage * stageFloats;
        float* sV = sA + BM * BNc;
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt, ni = t % nt;
            for (int kk = 0; kk < kt; ++kk) {
                FragA_rm a; wmma::load_matrix_sync(a, sV + (long)mi * 16 * BM + (long)kk * 8, BM);
                FragB_rm b; wmma::load_matrix_sync(b, sA + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                FragA_rm ah; FragB_rm bh, bl;
                #pragma unroll
                for (int e = 0; e < a.num_elements; ++e) ah.x[e] = rtn_tf32(a.x[e]);
                #pragma unroll
                for (int e = 0; e < b.num_elements; ++e) { float hv = trunc_tf32(b.x[e]); bh.x[e] = hv; bl.x[e] = b.x[e] - hv; }
                wmma::mma_sync(accW[t], ah, bh, accW[t]);
                wmma::mma_sync(accW[t], ah, bl, accW[t]);
            }
        }
        __syncthreads();
    }

    // ---- stage W to smem, load T, compute YT = T^T @ W ----
    float* sW = smem;                  // BLK*BNc
    float* sT = smem + BLK * BNc;      // BLK*BLK
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accW[t], BNc, wmma::mem_row_major);
    }
    const float* Tb = Tbuf + (long)bid * strideTb;
    for (int idx = tid; idx < BLK * BLK; idx += nthr) {
        int r = idx / BLK, cc = idx % BLK;
        sT[idx] = Tb[(long)r * strideTk + (long)cc * strideTn];
    }
    __syncthreads();

    FragAcc accYT[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accYT[t], 0.0f);
    const int ktY = BLK / 8;
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        for (int kk = 0; kk < ktY; ++kk) {
            // T^T[a,k] = T[k,a] = sT[k*BLK+a] -> matrix_a col_major view ldm=BLK
            FragA_cm at; wmma::load_matrix_sync(at, sT + (long)mi * 16 + (long)kk * 8 * BLK, BLK);
            FragB_rm bw; wmma::load_matrix_sync(bw, sW + (long)kk * 8 * BNc + (long)ni * 16, BNc);
            // tf32x3 (3 MMA) coupling dot
            FragA_cm ath, atl; FragB_rm bwh, bwl;
            #pragma unroll
            for (int e = 0; e < at.num_elements; ++e) { float hv = trunc_tf32(at.x[e]); ath.x[e]=hv; atl.x[e]=trunc_tf32(at.x[e]-hv); }
            #pragma unroll
            for (int e = 0; e < bw.num_elements; ++e) { float hv = trunc_tf32(bw.x[e]); bwh.x[e]=hv; bwl.x[e]=trunc_tf32(bw.x[e]-hv); }
            wmma::mma_sync(accYT[t], ath, bwh, accYT[t]);
            wmma::mma_sync(accYT[t], ath, bwl, accYT[t]);
            wmma::mma_sync(accYT[t], atl, bwh, accYT[t]);
        }
    }
    __syncthreads();
    // overwrite sW with YT
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accYT[t], BNc, wmma::mem_row_major);
    }
    __syncthreads();
    // sW holds YT[a,n] = sW[a*BNc+n]

    // ---- apply: A_trail -= V @ YT ----
    float* s2V = smem + BLK * BNc;       // BM*BLK
    float* s2A = s2V + BM * BLK;         // BM*BNc
    float* AoutR = Aout + (long)bid * strideAb + (long)j * strideAn + jb;
    const int ktD = BLK / 8;
    for (int ci = 0; ci < nchunks; ++ci) {
        int r0 = ci * BM;
        for (int idx = tid; idx < BM * BLK; idx += nthr) {
            int rr = idx / BLK, a = idx % BLK, gr = r0 + rr;
            s2V[idx] = (gr < pheight) ? Vb[(long)a * strideVk + (long)gr * strideVn] : 0.0f;
        }
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
            s2A[idx] = (gr < pheight && gc < ncols) ? Ab[(long)gr * strideAn + gc] : 0.0f;
        }
        __syncthreads();
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt, ni = t % nt;
            FragAcc accD; wmma::fill_fragment(accD, 0.0f);
            for (int kk = 0; kk < ktD; ++kk) {
                FragA_rm vrow; wmma::load_matrix_sync(vrow, s2V + (long)mi * 16 * BLK + (long)kk * 8, BLK);
                FragB_rm yt;   wmma::load_matrix_sync(yt, sW + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                FragA_rm vh; FragB_rm yh, yl;
                #pragma unroll
                for (int e = 0; e < vrow.num_elements; ++e) vh.x[e] = rtn_tf32(vrow.x[e]);
                #pragma unroll
                for (int e = 0; e < yt.num_elements; ++e) { float hv = trunc_tf32(yt.x[e]); yh.x[e]=hv; yl.x[e]=yt.x[e]-hv; }
                wmma::mma_sync(accD, vh, yh, accD);
                wmma::mma_sync(accD, vh, yl, accD);
            }
            // accO = orig - delta, in accumulator fragment space (load orig from s2A)
            FragAcc accO; wmma::load_matrix_sync(accO, s2A + (long)mi * 16 * BNc + (long)ni * 16, BNc, wmma::mem_row_major);
            #pragma unroll
            for (int e = 0; e < accO.num_elements; ++e) accO.x[e] -= accD.x[e];
            int gr0 = r0 + mi * 16, gc0 = c0 + ni * 16;
            if (gr0 + 16 <= pheight && gc0 + 16 <= ncols)
                wmma::store_matrix_sync(AoutR + (long)gr0 * strideAn + gc0, accO, strideAn, wmma::mem_row_major);
            else
                wmma::store_matrix_sync(s2A + (long)mi * 16 * BNc + (long)ni * 16, accO, BNc, wmma::mem_row_major);
        }
        __syncthreads();
        // masked tail for partial tiles
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
            int mi = rr / 16, ni = cc / 16, gr0 = r0 + mi * 16, gc0 = c0 + ni * 16;
            if (gr < pheight && gc < ncols && !(gr0 + 16 <= pheight && gc0 + 16 <= ncols))
                AoutR[(long)gr * strideAn + gc] = s2A[idx];
        }
        __syncthreads();
    }
}

toolUseResult.content:
// Hand-CUDA n512 wide-trailing (brief-41): EXPLICIT-smem fused trailing matching
// the Triton _trailing_fused_kernel (grid=(col_tiles, B), one block per
// (col_tile, matrix)). RTN-tf32x2 accuracy. Goal: ring-buffer staging sized to
// fit block-limit>=9 (smem<=24KB) so eligible warps rise above the Triton tile's
// block-limit-7 / 28KB wall.
//
// Per block: BLK=32 reflectors, BNc=32 trail cols, reduce over pheight rows in
// chunks of BM=32. W=V^T@A (32x32), YT=T^T@W (32x32), A_trail -= V@YT.
// Block = NW warps (default 2 -> 64 threads). 4 output tiles (2x2 of 16x16),
// warp w owns tiles {t : t%NW==w}. Accumulators live in registers (decoupled
// from the smem ring).
#include <mma.h>
using namespace nvcuda;

typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragA_rm;
typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::col_major> FragA_cm;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragB_rm;
typedef wmma::fragment<wmma::accumulator, 16, 16, 8, float> FragAcc;

__device__ __forceinline__ float rtn_tf32(float v) {
    int i = __float_as_int(v);
    i = (i + 0x1000) & 0xFFFFE000;
    return __int_as_float(i);
}
__device__ __forceinline__ float trunc_tf32(float v) {
    return __int_as_float(__float_as_int(v) & 0xFFFFE000);
}

// smem layout (single dynamic buffer, reused across phases):
//  Phase reduce: ring of NS stages, each [ sA: BM*BNc | sV: BLK*BM ]  (8192 B/stage)
//  Phase YT:     sW (BLK*BNc) | sT (BLK*BLK)
//  Phase apply:  sW (BLK*BNc, holds YT) | s2V (BM*BLK) | s2A (BM*BNc)
// Peak = max(NS*8192, (BLK*BNc+BLK*BLK)*4, (BLK*BNc+BM*BLK+BM*BNc)*4).
// For 32/32/32: NS*8192, 4096+4096=8192, 4096+4096+4096=12288. NS=3 -> 24576 peak.

extern "C" __global__ void wt_fused(
    const float* __restrict__ A, const float* __restrict__ Vbuf,
    const float* __restrict__ Tbuf, float* __restrict__ Aout,
    int B, int N, int j, int pheight, int ncols, int jb,
    int strideAb, int strideAn,
    int strideVb, int strideVk, int strideVn,
    int strideTb, int strideTk, int strideTn,
    int BLK, int BM, int BNc, int NS, int PREC)
{
    const int col_tile = blockIdx.x;
    const int bid = blockIdx.y;
    if (bid >= B) return;
    const int c0 = col_tile * BNc;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int NW = nthr >> 5;

    extern __shared__ float smem[];
    const int stageFloats = BM * BNc + BLK * BM;
    const int nchunks = (pheight + BM - 1) / BM;
    const int mt = BLK / 16, nt = BNc / 16;
    const int ntiles = mt * nt;            // 4

    const float* Ab = A + (long)bid * strideAb + (long)j * strideAn + jb;
    const float* Vb = Vbuf + (long)bid * strideVb;

    // ---- reduction: W = V^T @ A_trail ----
    FragAcc accW[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accW[t], 0.0f);

    auto load_chunk = [&](int ci, int stage) {
        float* sA = smem + (long)stage * stageFloats;
        float* sV = sA + BM * BNc;
        const int r0 = ci * BM;
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
            sA[idx] = (gr < pheight && gc < ncols) ? Ab[(long)gr * strideAn + gc] : 0.0f;
        }
        for (int idx = tid; idx < BLK * BM; idx += nthr) {
            int k = idx / BM, rr = idx % BM, gr = r0 + rr;
            sV[idx] = (gr < pheight) ? Vb[(long)k * strideVk + (long)gr * strideVn] : 0.0f;
        }
    };

    int prefetch = NS - 1; if (prefetch > nchunks) prefetch = nchunks;
    for (int ci = 0; ci < prefetch; ++ci) load_chunk(ci, ci % NS);
    __syncthreads();

    const int kt = BM / 8;   // 4
    for (int ci = 0; ci < nchunks; ++ci) {
        int stage = ci % NS;
        int nx = ci + prefetch;
        if (nx < nchunks) load_chunk(nx, nx % NS);
        __syncthreads();
        float* sA = smem + (long)stage * stageFloats;
        float* sV = sA + BM * BNc;
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt, ni = t % nt;
            for (int kk = 0; kk < kt; ++kk) {
                FragA_rm a; wmma::load_matrix_sync(a, sV + (long)mi * 16 * BM + (long)kk * 8, BM);
                FragB_rm b; wmma::load_matrix_sync(b, sA + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                FragA_rm ah; FragB_rm bh, bl;
                #pragma unroll
                for (int e = 0; e < a.num_elements; ++e) ah.x[e] = rtn_tf32(a.x[e]);
                #pragma unroll
                for (int e = 0; e < b.num_elements; ++e) { float hv = trunc_tf32(b.x[e]); bh.x[e] = hv; bl.x[e] = b.x[e] - hv; }
                wmma::mma_sync(accW[t], ah, bh, accW[t]);
                wmma::mma_sync(accW[t], ah, bl, accW[t]);
            }
        }
        __syncthreads();
    }

    // ---- stage W to smem, load T, compute YT = T^T @ W ----
    float* sW = smem;                  // BLK*BNc
    float* sT = smem + BLK * BNc;      // BLK*BLK
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accW[t], BNc, wmma::mem_row_major);
    }
    const float* Tb = Tbuf + (long)bid * strideTb;
    for (int idx = tid; idx < BLK * BLK; idx += nthr) {
        int r = idx / BLK, cc = idx % BLK;
        sT[idx] = Tb[(long)r * strideTk + (long)cc * strideTn];
    }
    __syncthreads();

    FragAcc accYT[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accYT[t], 0.0f);
    const int ktY = BLK / 8;
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        for (int kk = 0; kk < ktY; ++kk) {
            // T^T[a,k] = T[k,a] = sT[k*BLK+a] -> matrix_a col_major view ldm=BLK
            FragA_cm at; wmma::load_matrix_sync(at, sT + (long)mi * 16 + (long)kk * 8 * BLK, BLK);
            FragB_rm bw; wmma::load_matrix_sync(bw, sW + (long)kk * 8 * BNc + (long)ni * 16, BNc);
            // tf32x3 (3 MMA) coupling dot
            FragA_cm ath, atl; FragB_rm bwh, bwl;
            #pragma unroll
            for (int e = 0; e < at.num_elements; ++e) { float hv = trunc_tf32(at.x[e]); ath.x[e]=hv; atl.x[e]=trunc_tf32(at.x[e]-hv); }
            #pragma unroll
            for (int e = 0; e < bw.num_elements; ++e) { float hv = trunc_tf32(bw.x[e]); bwh.x[e]=hv; bwl.x[e]=trunc_tf32(bw.x[e]-hv); }
            wmma::mma_sync(accYT[t], ath, bwh, accYT[t]);
            wmma::mma_sync(accYT[t], ath, bwl, accYT[t]);
            wmma::mma_sync(accYT[t], atl, bwh, accYT[t]);
        }
    }
    __syncthreads();
    // overwrite sW with YT
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accYT[t], BNc, wmma::mem_row_major);
    }
    __syncthreads();
    // sW holds YT[a,n] = sW[a*BNc+n]

    // ---- apply: A_trail -= V @ YT ----
    float* s2V = smem + BLK * BNc;       // BM*BLK
    float* s2A = s2V + BM * BLK;         // BM*BNc
    float* AoutR = Aout + (long)bid * strideAb + (long)j * strideAn + jb;
    const int ktD = BLK / 8;
    for (int ci = 0; ci < nchunks; ++ci) {
        int r0 = ci * BM;
        for (int idx = tid; idx < BM * BLK; idx += nthr) {
            int rr = idx / BLK, a = idx % BLK, gr = r0 + rr;
            s2V[idx] = (gr < pheight) ? Vb[(long)a * strideVk + (long)gr * strideVn] : 0.0f;
        }
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
            s2A[idx] = (gr < pheight && gc < ncols) ? Ab[(long)gr * strideAn + gc] : 0.0f;
        }
        __syncthreads();
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt, ni = t % nt;
            FragAcc accD; wmma::fill_fragment(accD, 0.0f);
            for (int kk = 0; kk < ktD; ++kk) {
                FragA_rm vrow; wmma::load_matrix_sync(vrow, s2V + (long)mi * 16 * BLK + (long)kk * 8, BLK);
                FragB_rm yt;   wmma::load_matrix_sync(yt, sW + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                FragA_rm vh; FragB_rm yh, yl;
                #pragma unroll
                for (int e = 0; e < vrow.num_elements; ++e) vh.x[e] = rtn_tf32(vrow.x[e]);
                #pragma unroll
                for (int e = 0; e < yt.num_elements; ++e) { float hv = trunc_tf32(yt.x[e]); yh.x[e]=hv; yl.x[e]=yt.x[e]-hv; }
                wmma::mma_sync(accD, vh, yh, accD);
                wmma::mma_sync(accD, vh, yl, accD);
            }
            // accO = orig - delta, in accumulator fragment space (load orig from s2A)
            FragAcc accO; wmma::load_matrix_sync(accO, s2A + (long)mi * 16 * BNc + (long)ni * 16, BNc, wmma::mem_row_major);
            #pragma unroll
            for (int e = 0; e < accO.num_elements; ++e) accO.x[e] -= accD.x[e];
            int gr0 = r0 + mi * 16, gc0 = c0 + ni * 16;
            if (gr0 + 16 <= pheight && gc0 + 16 <= ncols)
                wmma::store_matrix_sync(AoutR + (long)gr0 * strideAn + gc0, accO, strideAn, wmma::mem_row_major);
            else
                wmma::store_matrix_sync(s2A + (long)mi * 16 * BNc + (long)ni * 16, accO, BNc, wmma::mem_row_major);
        }
        __syncthreads();
        // masked tail for partial tiles
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
            int mi = rr / 16, ni = cc / 16, gr0 = r0 + mi * 16, gc0 = c0 + ni * 16;
            if (gr < pheight && gc < ncols && !(gr0 + 16 <= pheight && gc0 + 16 <= ncols))
                AoutR[(long)gr * strideAn + gc] = s2A[idx];
        }
        __syncthreads();
    }
}

