                wmma::store_matrix_sync(s2A + (long)mi * 16 * BNc + (long)ni * 16, accO, BNc, wmma::mem_row_major);
        }
        __syncthreads();
        // masked tail for partial tiles
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
            int mi = rr / 16, ni = cc / 16, gr0 = r0 + mi * 16, gc0 = c0 + ni * 16;
            if (gr < pheight && gc < ncols && !(gr0 + 16 <= pheight && gc0 + 16 <= ncols))
                AoutR[(long)gr * strideAn + gc] = s2A[idx];
        }
        __syncthreads();
    }
