// Hand-CUDA n512 wide-trailing v2 (brief-41): cp.async staging + BULK pre-split
// of operands in smem (RTN tf32x2), so the MMA loop has ZERO per-element register
// conversion (the v1 wall). Per stage smem: sVr(BLK*BM) | sAh(BM*BNc) | sAl(BM*BNc).
// = 3*1024 floats = 12KB/stage. 2-deep=24KB (block-limit 9), tested via occ query.
#include <mma.h>
#include <cuda_pipeline.h>
using namespace nvcuda;

typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragA_rm;
typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::col_major> FragA_cm;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragB_rm;
typedef wmma::fragment<wmma::accumulator, 16, 16, 8, float> FragAcc;

__device__ __forceinline__ float rtn_tf32(float v) {
    int i = __float_as_int(v); i = (i + 0x1000) & 0xFFFFE000; return __int_as_float(i);
}
__device__ __forceinline__ float trunc_tf32(float v) {
    return __int_as_float(__float_as_int(v) & 0xFFFFE000);
}

extern "C" __global__ void wt_fused(
    const float* __restrict__ A, const float* __restrict__ Vbuf,
    const float* __restrict__ Tbuf, float* __restrict__ Aout,
    int B, int N, int j, int pheight, int ncols, int jb,
    int strideAb, int strideAn,
    int strideVb, int strideVk, int strideVn,
    int strideTb, int strideTk, int strideTn,
    int BLK, int BM, int BNc, int NS, int PREC)
{
    const int col_tile = blockIdx.x;
    const int bid = blockIdx.y;
    if (bid >= B) return;
    const int c0 = col_tile * BNc;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int NW = nthr >> 5;

    extern __shared__ float smem[];
    const int ABN = BM * BNc, VBM = BLK * BM;
    const int rawStage = ABN + VBM;                 // raw A + raw V per stage (for cp.async)
    const int splitStage = VBM + ABN + ABN;         // sVr + sAh + sAl per stage
    const int nchunks = (pheight + BM - 1) / BM;
    const int mt = BLK / 16, nt = BNc / 16;
    const int ntiles = mt * nt;

    const float* Ab = A + (long)bid * strideAb + (long)j * strideAn + jb;
    const float* Vb = Vbuf + (long)bid * strideVb;

    // raw staging buffer (cp.async dest), then split buffer. We overlap: raw ring of
    // NS stages at smem[0..NS*rawStage), split ring of NS stages at smem[NS*rawStage..).
    float* rawBase = smem;
    float* splitBase = smem + (long)NS * rawStage;

    FragAcc accW[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accW[t], 0.0f);

    // cp.async raw A (BM x BNc, but A_trail is strided by strideAn so per-row copy)
    // and raw V (BLK x BM, strided by strideVn). cp.async needs contiguous 16B chunks;
    // A_trail rows are contiguous in cols (BNc floats = up to 128B), V rows (over rr)
    // are strided -> fall back to scalar for V. We cp.async A row-by-row (BNc contiguous).
    auto load_raw = [&](int ci, int rstage) {
        float* rA = rawBase + (long)rstage * rawStage;
        float* rV = rA + ABN;
        const int r0 = ci * BM;
        // A: BM rows, each BNc contiguous floats from Ab[(r0+rr)*strideAn + c0]
        for (int idx = tid; idx < ABN; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
            rA[idx] = (gr < pheight && gc < ncols) ? Ab[(long)gr * strideAn + gc] : 0.0f;
        }
        // V: BLK refl x BM cols; Vt[k, r0+rr] strided by strideVn
        for (int idx = tid; idx < VBM; idx += nthr) {
            int k = idx / BM, rr = idx % BM, gr = r0 + rr;
            rV[idx] = (gr < pheight) ? Vb[(long)k * strideVk + (long)gr * strideVn] : 0.0f;
        }
    };
    // split raw stage -> sVr / sAh / sAl
    auto split_stage = [&](int rstage, int sstage) {
        float* rA = rawBase + (long)rstage * rawStage;
        float* rV = rA + ABN;
        float* sVr = splitBase + (long)sstage * splitStage;
        float* sAh = sVr + VBM;
        float* sAl = sAh + ABN;
        for (int idx = tid; idx < VBM; idx += nthr) sVr[idx] = rtn_tf32(rV[idx]);
        for (int idx = tid; idx < ABN; idx += nthr) { float h = trunc_tf32(rA[idx]); sAh[idx] = h; sAl[idx] = rA[idx] - h; }
    };

    int prefetch = NS - 1; if (prefetch > nchunks) prefetch = nchunks;
    for (int ci = 0; ci < prefetch; ++ci) { load_raw(ci, ci % NS); }
    __syncthreads();
    for (int ci = 0; ci < prefetch; ++ci) { split_stage(ci % NS, ci % NS); }
    __syncthreads();

    const int kt = BM / 8;
    for (int ci = 0; ci < nchunks; ++ci) {
        int stage = ci % NS;
        int nx = ci + prefetch;
        if (nx < nchunks) { load_raw(nx, nx % NS); }
        // note: split of nx happens after we consume current; to keep it simple split nx now
        // (raw nx just loaded into nx%NS == stage if NS small; but prefetch keeps them distinct)
        __syncthreads();
        if (nx < nchunks) { split_stage(nx % NS, nx % NS); }
        float* sVr = splitBase + (long)stage * splitStage;
        float* sAh = sVr + VBM;
        float* sAl = sAh + ABN;
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt, ni = t % nt;
            for (int kk = 0; kk < kt; ++kk) {
                FragA_rm ah; wmma::load_matrix_sync(ah, sVr + (long)mi * 16 * BM + (long)kk * 8, BM);
                FragB_rm bh; wmma::load_matrix_sync(bh, sAh + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                FragB_rm bl; wmma::load_matrix_sync(bl, sAl + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                wmma::mma_sync(accW[t], ah, bh, accW[t]);
                wmma::mma_sync(accW[t], ah, bl, accW[t]);
            }
        }
        __syncthreads();
    }

    // ---- YT = T^T @ W ----  (reuse splitBase region as scratch)
    float* sW = splitBase;                 // BLK*BNc
    float* sT = splitBase + BLK * BNc;     // BLK*BLK
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accW[t], BNc, wmma::mem_row_major);
    }
    const float* Tb = Tbuf + (long)bid * strideTb;
    for (int idx = tid; idx < BLK * BLK; idx += nthr) { int r = idx / BLK, cc = idx % BLK; sT[idx] = Tb[(long)r * strideTk + (long)cc * strideTn]; }
    __syncthreads();
    FragAcc accYT[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accYT[t], 0.0f);
    const int ktY = BLK / 8;
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        for (int kk = 0; kk < ktY; ++kk) {
            FragA_cm at; wmma::load_matrix_sync(at, sT + (long)mi * 16 + (long)kk * 8 * BLK, BLK);
            FragB_rm bw; wmma::load_matrix_sync(bw, sW + (long)kk * 8 * BNc + (long)ni * 16, BNc);
            FragA_cm ath, atl; FragB_rm bwh, bwl;
            #pragma unroll
            for (int e = 0; e < at.num_elements; ++e) { float h = trunc_tf32(at.x[e]); ath.x[e]=h; atl.x[e]=trunc_tf32(at.x[e]-h); }
            #pragma unroll
            for (int e = 0; e < bw.num_elements; ++e) { float h = trunc_tf32(bw.x[e]); bwh.x[e]=h; bwl.x[e]=trunc_tf32(bw.x[e]-h); }
            wmma::mma_sync(accYT[t], ath, bwh, accYT[t]);
            wmma::mma_sync(accYT[t], ath, bwl, accYT[t]);
            wmma::mma_sync(accYT[t], atl, bwh, accYT[t]);
        }
    }
    __syncthreads();
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accYT[t], BNc, wmma::mem_row_major);
    }
    __syncthreads();
    // sW holds YT. Pre-round YT once into sYr (RTN not needed; YT is the hi+lo operand).
    // For apply RTN-tf32x2: V rounded, YT split hi+lo. Pre-split YT into sW->sYh,sYl.
    float* sYh = splitBase + BLK * BNc;            // reuse region after sW
    float* sYl = sYh + BLK * BNc;
    for (int idx = tid; idx < BLK * BNc; idx += nthr) { float h = trunc_tf32(sW[idx]); sYh[idx] = h; sYl[idx] = sW[idx] - h; }
    __syncthreads();

    // ---- apply: A_trail -= V @ YT ----
    // staging: sV2r (rounded V, BM*BLK) | sD (delta BM*BNc). sYh/sYl persist.
    float* sV2r = sYl + BLK * BNc;
    float* sD   = sV2r + BM * BLK;
    float* AoutR = Aout + (long)bid * strideAb + (long)j * strideAn + jb;
    const int ktD = BLK / 8;
    for (int ci = 0; ci < nchunks; ++ci) {
        int r0 = ci * BM;
        for (int idx = tid; idx < BM * BLK; idx += nthr) {
            int rr = idx / BLK, a = idx % BLK, gr = r0 + rr;
            float v = (gr < pheight) ? Vb[(long)a * strideVk + (long)gr * strideVn] : 0.0f;
            sV2r[idx] = rtn_tf32(v);
        }
        __syncthreads();
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt, ni = t % nt;
            FragAcc accD; wmma::fill_fragment(accD, 0.0f);
            for (int kk = 0; kk < ktD; ++kk) {
                FragA_rm vh; wmma::load_matrix_sync(vh, sV2r + (long)mi * 16 * BLK + (long)kk * 8, BLK);
                FragB_rm yh; wmma::load_matrix_sync(yh, sYh + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                FragB_rm yl; wmma::load_matrix_sync(yl, sYl + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                wmma::mma_sync(accD, vh, yh, accD);
                wmma::mma_sync(accD, vh, yl, accD);
            }
            wmma::store_matrix_sync(sD + (long)mi * 16 * BNc + (long)ni * 16, accD, BNc, wmma::mem_row_major);
        }
        __syncthreads();
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
