// Hand-CUDA n512 wide-trailing v3 (brief-41): TRUE cp.async double/triple-buffer
// staging (the brief's specified mechanism). v1 ncu showed the wall is
// stall_long_scoreboard=0.56 (global-load LATENCY, tensor pipe 7% idle) from the
// SYNCHRONOUS prefetch loads -- cp.async overlaps that latency with MMA compute.
// Operands converted to tf32 in-register at MMA time (v2 pre-split regressed:
// extra smem write traffic > the conversion saved). RTN tf32x2 accuracy.
//
// Per stage: sA(BM*BNc) | sV(BLK*BM) = 2048 floats = 8KB. NS=3 -> 24KB (block-limit 9).
#include <mma.h>
#include <cuda_pipeline.h>
using namespace nvcuda;

typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragA_rm;
typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::col_major> FragA_cm;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragB_rm;
typedef wmma::fragment<wmma::accumulator, 16, 16, 8, float> FragAcc;

__device__ __forceinline__ float rtn_tf32(float v) {
    int i = __float_as_int(v); i = (i + 0x1000) & 0xFFFFE000; return __int_as_float(i);
}
__device__ __forceinline__ float trunc_tf32(float v) {
    return __int_as_float(__float_as_int(v) & 0xFFFFE000);
}

extern "C" __global__ void wt_fused(
    const float* __restrict__ A, const float* __restrict__ Vbuf,
    const float* __restrict__ Tbuf, float* __restrict__ Aout,
    int B, int N, int j, int pheight, int ncols, int jb,
    int strideAb, int strideAn,
    int strideVb, int strideVk, int strideVn,
    int strideTb, int strideTk, int strideTn,
    int BLK, int BM, int BNc, int NS, int PREC)
{
    const int col_tile = blockIdx.x;
    const int bid = blockIdx.y;
    if (bid >= B) return;
    const int c0 = col_tile * BNc;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int NW = nthr >> 5;

    extern __shared__ float smem[];
    const int ABN = BM * BNc, VBM = BLK * BM;
    const int stageFloats = ABN + VBM;
    const int nchunks = (pheight + BM - 1) / BM;
    const int mt = BLK / 16, nt = BNc / 16;
    const int ntiles = mt * nt;

    const float* Ab = A + (long)bid * strideAb + (long)j * strideAn + jb;
    const float* Vb = Vbuf + (long)bid * strideVb;

    FragAcc accW[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accW[t], 0.0f);

    // cp.async load of chunk ci into stage buffer. A_trail row = BNc contiguous floats
    // -> copy as float4 (16B) groups. V is strided over rr -> copy 4B per element.
    auto load_async = [&](int ci, int stage) {
        float* sA = smem + (long)stage * stageFloats;
        float* sV = sA + ABN;
        const int r0 = ci * BM;
        const bool fullRows = (r0 + BM <= pheight);
        const bool fullCols = (c0 + BNc <= ncols);
        // A: BM*BNc floats. If full tile + 16B-aligned, use float4 cp.async.
        if (fullRows && fullCols) {
            // each row BNc floats contiguous; BNc=32 -> 8 float4 per row.
            int vec = ABN / 4;   // number of float4
            for (int q = tid; q < vec; q += nthr) {
                int f0 = q * 4;            // float index in tile
                int rr = f0 / BNc, cc = f0 % BNc;
                const float* src = Ab + (long)(r0 + rr) * strideAn + (c0 + cc);
                __pipeline_memcpy_async(&sA[f0], src, 16);
            }
        } else {
            for (int idx = tid; idx < ABN; idx += nthr) {
                int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
                float v = (gr < pheight && gc < ncols) ? Ab[(long)gr * strideAn + gc] : 0.0f;
                __pipeline_memcpy_async(&sA[idx], &v, 4);   // note: src must be addressable; use scalar store instead
            }
        }
        // V: strided; do scalar cp.async per element (4B). source Vb[k*svk + gr*svn].
        for (int idx = tid; idx < VBM; idx += nthr) {
            int k = idx / BM, rr = idx % BM, gr = r0 + rr;
            if (gr < pheight) {
                const float* src = Vb + (long)k * strideVk + (long)gr * strideVn;
                __pipeline_memcpy_async(&sV[idx], src, 4);
            } else {
                sV[idx] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    int prefetch = NS - 1; if (prefetch > nchunks) prefetch = nchunks;
    for (int ci = 0; ci < prefetch; ++ci) load_async(ci, ci % NS);

    const int kt = BM / 8;
    for (int ci = 0; ci < nchunks; ++ci) {
        int stage = ci % NS;
        int nx = ci + prefetch;
        if (nx < nchunks) load_async(nx, nx % NS);
        // wait until the chunk we're about to consume is ready: there are
        // (#committed - already-consumed) groups in flight; we need the OLDEST
        // (current ci's) done -> wait until at most 'prefetch' groups remain.
        __pipeline_wait_prior(prefetch);
        __syncthreads();
        float* sA = smem + (long)stage * stageFloats;
        float* sV = sA + ABN;
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt, ni = t % nt;
            for (int kk = 0; kk < kt; ++kk) {
                FragA_rm a; wmma::load_matrix_sync(a, sV + (long)mi * 16 * BM + (long)kk * 8, BM);
                FragB_rm b; wmma::load_matrix_sync(b, sA + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                FragA_rm ah; FragB_rm bh, bl;
                #pragma unroll
                for (int e = 0; e < a.num_elements; ++e) ah.x[e] = rtn_tf32(a.x[e]);
                #pragma unroll
                for (int e = 0; e < b.num_elements; ++e) { float hv = trunc_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=b.x[e]-hv; }
                wmma::mma_sync(accW[t], ah, bh, accW[t]);
                wmma::mma_sync(accW[t], ah, bl, accW[t]);
            }
        }
        __syncthreads();
    }
    __pipeline_wait_prior(0);

    // ---- YT = T^T @ W ----
    float* sW = smem;                  // BLK*BNc
    float* sT = smem + BLK * BNc;      // BLK*BLK
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accW[t], BNc, wmma::mem_row_major);
    }
    const float* Tb = Tbuf + (long)bid * strideTb;
    for (int idx = tid; idx < BLK * BLK; idx += nthr) { int r = idx / BLK, cc = idx % BLK; sT[idx] = Tb[(long)r * strideTk + (long)cc * strideTn]; }
    __syncthreads();
    FragAcc accYT[4];
    #pragma unroll
    for (int t = 0; t < 4; ++t) wmma::fill_fragment(accYT[t], 0.0f);
    const int ktY = BLK / 8;
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        for (int kk = 0; kk < ktY; ++kk) {
            FragA_cm at; wmma::load_matrix_sync(at, sT + (long)mi * 16 + (long)kk * 8 * BLK, BLK);
            FragB_rm bw; wmma::load_matrix_sync(bw, sW + (long)kk * 8 * BNc + (long)ni * 16, BNc);
            FragA_cm ath, atl; FragB_rm bwh, bwl;
            #pragma unroll
            for (int e = 0; e < at.num_elements; ++e) { float h = trunc_tf32(at.x[e]); ath.x[e]=h; atl.x[e]=trunc_tf32(at.x[e]-h); }
            #pragma unroll
            for (int e = 0; e < bw.num_elements; ++e) { float h = trunc_tf32(bw.x[e]); bwh.x[e]=h; bwl.x[e]=trunc_tf32(bw.x[e]-h); }
            wmma::mma_sync(accYT[t], ath, bwh, accYT[t]);
            wmma::mma_sync(accYT[t], ath, bwl, accYT[t]);
            wmma::mma_sync(accYT[t], atl, bwh, accYT[t]);
        }
    }
    __syncthreads();
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
        if (t >= ntiles) break;
        if ((t % NW) != warp) continue;
        int mi = t / nt, ni = t % nt;
        wmma::store_matrix_sync(sW + (long)mi * 16 * BNc + (long)ni * 16, accYT[t], BNc, wmma::mem_row_major);
    }
    __syncthreads();

    // ---- apply: A_trail -= V @ YT (cp.async V chunks) ----
    float* s2V = smem + BLK * BNc;
    float* sD  = s2V + BM * BLK;
    float* AoutR = Aout + (long)bid * strideAb + (long)j * strideAn + jb;
    const int ktD = BLK / 8;
    for (int ci = 0; ci < nchunks; ++ci) {
        int r0 = ci * BM;
        for (int idx = tid; idx < BM * BLK; idx += nthr) {
            int rr = idx / BLK, a = idx % BLK, gr = r0 + rr;
            s2V[idx] = (gr < pheight) ? Vb[(long)a * strideVk + (long)gr * strideVn] : 0.0f;
        }
        __syncthreads();
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            if (t >= ntiles) break;
            if ((t % NW) != warp) continue;
            int mi = t / nt, ni = t % nt;
            FragAcc accD; wmma::fill_fragment(accD, 0.0f);
            for (int kk = 0; kk < ktD; ++kk) {
                FragA_rm vrow; wmma::load_matrix_sync(vrow, s2V + (long)mi * 16 * BLK + (long)kk * 8, BLK);
                FragB_rm yt;   wmma::load_matrix_sync(yt, sW + (long)kk * 8 * BNc + (long)ni * 16, BNc);
                FragA_rm vh; FragB_rm yh, yl;
                #pragma unroll
                for (int e = 0; e < vrow.num_elements; ++e) vh.x[e] = rtn_tf32(vrow.x[e]);
                #pragma unroll
                for (int e = 0; e < yt.num_elements; ++e) { float h = trunc_tf32(yt.x[e]); yh.x[e]=h; yl.x[e]=yt.x[e]-h; }
                wmma::mma_sync(accD, vh, yh, accD);
                wmma::mma_sync(accD, vh, yl, accD);
            }
            wmma::store_matrix_sync(sD + (long)mi * 16 * BNc + (long)ni * 16, accD, BNc, wmma::mem_row_major);
        }
        __syncthreads();
        for (int idx = tid; idx < BM * BNc; idx += nthr) {
            int rr = idx / BNc, cc = idx % BNc, gr = r0 + rr, gc = c0 + cc;
            if (gr < pheight && gc < ncols) AoutR[(long)gr * strideAn + gc] = Ab[(long)gr * strideAn + gc] - sD[idx];
        }
        __syncthreads();
    }
}

